Object.assign(classes, {
  a: ['NativeRenderContext', 'Native renderer context constructed per NativeSoftwareGraphicsToolkit context slot, retaining its toolkit and native handle.'],
  e: ['NativeResource', 'Native resource disposal contract implemented by the native toolkit and its retained handles and drained by the native resource reaper.'],
  pa: ['NativeResourceReaper', 'Synchronizes native resource disposal and retains deferred resources in an intrusive queue while renderer users are active.'],
  ui: ['DeferredNativeResource', 'Intrusive queue node containing one NativeResource, queued and drained by the native resource reaper.'],
  oa: ['NativeSoftwareGraphicsToolkit', 'GraphicsToolkit implementation backed by native handles, native drawing calls and per-context native renderer objects.'],
  fr: ['LegacyOpenGlGraphicsToolkit', 'Direct GraphicsToolkit backend retaining jaggl.OpenGL, native vertex memory and the legacy OpenGL effect manager, distinct from the HardwareGraphicsToolkit backend.'],
  bq: ['LegacyOpenGlEffect', 'Abstract effect holding the direct legacy OpenGL toolkit; its concrete effects bind textures and OpenGL programs.'],
  iv: ['LegacyOpenGlEffectManager', 'Retains and selects the legacy OpenGL effect array and shared texture resources for the direct OpenGL toolkit.'],
  qa: ['SoftwareGraphicsToolkit', 'GraphicsToolkit backend retaining a software pixel target and constructing indexed, RGB and ARGB software sprite implementations.'],
  hr: ['ToolkitSprite', 'Renderer-independent sprite contract with dimensions, tinted and scaled drawing and shared affine rotation helpers.'],
  qd: ['SoftwareToolkitSprite', 'ToolkitSprite base holding the software renderer and sprite bounds, with shared software affine raster stepping state.'],
  mj: ['SoftwareRgbSprite', 'SoftwareToolkitSprite holding RGB pixels and treating zero pixels as transparent in its software blit paths.'],
  gl: ['SoftwareArgbSprite', 'SoftwareToolkitSprite whose pixel blit paths extract source alpha from the high byte and composite the retained ARGB pixels.'],
  uh: ['SoftwareIndexedSprite', 'SoftwareToolkitSprite holding byte pixel indices and an integer palette used by its software blit paths.'],
  ri: ['SpriteData', 'Decoded sprite record containing palette, byte pixel and optional alpha arrays with trimmed and full dimensions and offsets.'],
  cq: ['FullscreenCanvas', 'Canvas with a retained fullscreen Frame and volatile focus-loss flag, delegating frame release to the platform helper.'],
  ik: ['GraphicsToolkitManager', 'Manages renderer selection and recreation for the active canvas, retaining toolkit configurations, the current toolkit handle and its resource provider.'],
  gk: ['CompactMeshGeometry', 'Compact geometry record with short XYZ vertex arrays, face and texture data, integer bounds and per-axis vertex scaling.'],
  lk: ['SoftwareRasterizer', 'Static software pixel target, dimensions and clipping bounds used by primitive fill, line and blend kernels.'],
  ak: ['MenuScreen', 'Screen indexed by constructor mode, retaining selection state and drawing achievement, instruction, score and other game menu pages.'],
  qu: ['GameplaySession', 'Owns the game session update and draw entry points, entity and effect queues, gameplay controls, arena presentation and level progression.'],
  ud: ['MusicCrossfadeStream', 'PcmStream retaining two MidiPcmStreams and queued music tracks with crossfade duration and volume state.'],
  nt: ['TimedSceneEffect', 'Intrusive positioned effect with a countdown, type and render hook; its update reports expiry at zero.'],
  gw: ['SceneryParticle', 'TimedSceneEffect subclass retaining particle texture, scale, rotation, fade and motion state and drawing one of the scenery particle sprites.'],
  mb: ['GameInstructions', 'Static holder of the objective, controls, upgrades and drone instruction pages, plus unrelated obfuscator-distributed utility methods.'],
  rr: ['AbstractAudioSample', 'Intrusive audio-sample base with a scheduling position field, extended by the byte PCM sample record.'],
  qp: ['PcmSample', 'Audio sample containing byte PCM data, source rate, loop bounds and a ping-pong loop flag, consumed by PcmSampleStream.'],
  md: ['PcmMixerListener', 'Intrusive mixer listener with a sample countdown, release callback and rescheduling callback returning its next delay.'],
  tv: ['MusicTrack', 'Decodes a packed track into MIDI bytes and scans note events to build a per-instrument note-use table.'],
  sh: ['MidiFileReader', 'Parses MIDI track chunks and retains per-track byte positions, tick deltas, running status and tempo timing.'],
  tj: ['InstrumentNoteMask', 'Intrusive table entry with one byte mask per MIDI note, created by MusicTrack for each used instrument.'],
  uu: ['MusicVoice', 'Intrusive active MIDI voice holding its PCM stream, sample, patch and envelope with pitch, gain and release counters.'],
  rh: ['MidiNoteMixer', 'PcmStream retaining the active MIDI voice deque, parent MidiPcmStream and mixer for detached sample tails.'],
  td: ['MusicPatch', 'Instrument patch containing per-note PCM samples, envelope references, tuning and gain arrays and encoded sample identifiers.'],
  mq: ['MusicPatchEnvelope', 'Per-voice instrument envelope record with byte envelope curves and vibrato, decay and timing parameters.'],
  te: ['IntrusiveNodeHashTable', 'Non-Iterable intrusive hash table with sentinel buckets, long-key lookup, insertion and cursor-based iteration.'],
});

method('Sumoblitz', 'a', '(Z)V', 'releaseAllStatics', 'Calls the per-class static cleanup entry points across the complete client, preserving their original guard arguments.');
method('Sumoblitz', 'b', '(I)V', 'updateGame', 'Services startup and account state, advances screen transitions and gameplay, dispatches inbound packets and services background tasks.');
method('Sumoblitz', 'd', '(I)V', 'renderFrame', 'Selects startup or game presentation, renders screen fades, achievement notices and account overlays, copies the software raster when needed and presents the active toolkit.');
method('Sumoblitz', 'f', '(I)V', 'initializeGame', 'Configures the client, creates the dual MIDI crossfade stream and audio outputs and initializes the shared client services.');
method('Sumoblitz', 'g', '(B)V', 'advanceScreenTransition', 'Advances achievement notice time, screen fade phases and the gameplay session, then updates the selected menu screen.');
method('Sumoblitz', 'r', '(I)V', 'initializeGameArchives', 'Releases retained loading imagery, opens the game resource archives, initializes random state and constructs the graphics toolkit manager.');
method('Sumoblitz', 's', '(I)V', 'releaseStatics', 'Clears this class retained sprite and integer arrays with the original guard behavior.');
method('Sumoblitz', 'a', '(IIB)V', 'playEntityCollisionSound', 'Chooses a randomized sound for the nonplayer entity type and variant when it collides with the player and delegates sound playback.');

for (const [owner, original, descriptor, name, evidence] of [
  ['ms', 'a', '(Z)Z', 'isLinked', 'Tests whether the primary previous link is retained.'],
  ['jn', 'a', '(B)Z', 'isEmpty', 'Compares the primary next link of the sentinel to itself.'],
  ['jn', 'a', '(I)Lms;', 'last', 'Returns the sentinel previous node and initializes backward iteration.'],
  ['jn', 'a', '(Lms;B)V', 'addLast', 'Splices the node immediately before the sentinel, unlinking any existing primary membership.'],
  ['jn', 'a', '(Lms;I)V', 'addFirst', 'Splices the node immediately after the sentinel, unlinking any existing primary membership.'],
  ['jn', 'b', '(B)Lms;', 'removeLast', 'Unlinks and returns the node before the sentinel, or null when empty.'],
  ['jn', 'b', '(I)Lms;', 'first', 'Returns the sentinel next node and initializes forward iteration.'],
  ['jn', 'c', '(I)Lms;', 'removeFirst', 'Unlinks and returns the node after the sentinel, or null when empty.'],
  ['jn', 'd', '(B)Lms;', 'next', 'Advances the retained cursor through next links until the sentinel is reached.'],
  ['jn', 'd', '(I)Lms;', 'previous', 'Advances the retained cursor through previous links until the sentinel is reached.'],
  ['jn', 'e', '(I)V', 'clear', 'Unlinks all primary deque nodes and clears the retained cursor.'],
  ['cb', 'a', '(B)Lms;', 'last', 'Returns the deque tail and initializes this independent backward cursor.'],
  ['cb', 'a', '(BLms;)Lms;', 'startBackwardAt', 'Returns the supplied node or deque tail and retains its previous node for backward traversal.'],
  ['cb', 'a', '(ILms;)Lms;', 'startForwardAt', 'Returns the supplied node or deque head and retains its next node for forward traversal.'],
  ['cb', 'b', '(B)Lms;', 'first', 'Returns the deque head and initializes this independent forward cursor.'],
  ['cb', 'b', '(I)Lms;', 'next', 'Returns the retained cursor node and advances through its next link.'],
  ['cb', 'c', '(B)Lms;', 'previous', 'Returns the retained cursor node and advances through its previous link.'],
  ['hl', 'a', '(B)Lpj;', 'next', 'Returns the retained secondary cursor node and advances its secondary next link.'],
  ['hl', 'a', '(Lpj;B)V', 'addLast', 'Splices the dual-link node before the secondary sentinel after removing any existing secondary membership.'],
  ['hl', 'a', '(Lpj;I)Lpj;', 'startAt', 'Starts forward secondary traversal at the supplied node or the sentinel next node.'],
  ['hl', 'b', '(B)Lpj;', 'removeFirst', 'Unlinks and returns the secondary node after the sentinel.'],
  ['hl', 'b', '(I)Lpj;', 'first', 'Starts secondary traversal at the sentinel next node.'],
  ['ia', 'b', '(I)V', 'reset', 'Resets the bucket cursor to the first bucket next node and clears the last-returned node.'],
  ['um', 'a', '(I)Lms;', 'next', 'Advances the current bucket cursor and scans subsequent sentinel buckets for the next node.'],
  ['um', 'a', '(IJ)Lms;', 'get', 'Selects the bucket by masked long key and retains the next matching-key cursor position.'],
  ['um', 'a', '(ILms;J)V', 'put', 'Unlinks the node, sets its long key and splices it into the masked-key bucket.'],
  ['um', 'c', '(I)Lms;', 'first', 'Resets the bucket index and delegates iteration to the next node.'],
  ['hj', 'a', '()Lhj;', 'firstSubstream', 'Abstract first-child stream contract used by the audio scheduler and implemented by mixers and MIDI streams.'],
  ['hj', 'c', '()Lhj;', 'nextSubstream', 'Abstract subsequent-child stream contract used by the audio scheduler.'],
  ['hj', 'b', '([III)V', 'mixInto', 'Abstract PCM mixing entry point implemented by sample streams and mixers.'],
  ['hj', 'a', '(I)V', 'skip', 'Abstract entry point advancing the stream without producing output samples.'],
  ['hj', 'a', '([III)V', 'mixOrSkip', 'Mixes active streams into the supplied buffer and advances inactive streams without output.'],
  ['hj', 'b', '()I', 'priority', 'Returns the default audio scheduler priority of two hundred fifty-five.'],
  ['hj', 'd', '()I', 'activityWeight', 'Abstract scheduler activity-weight contract, returning zero for a pure mixer.'],
  ['al', 'b', '(Lhj;)V', 'addSubstream', 'Adds the stream to the mixer child deque.'],
  ['al', 'a', '(Lhj;)V', 'removeSubstream', 'Unlinks the stream from its primary intrusive deque.'],
  ['al', 'e', '()V', 'normalizeListenerDelays', 'Subtracts consumed samples from each listener delay and the next-listener countdown, then resets the consumed count.'],
  ['al', 'a', '(Lms;Lmd;)V', 'insertListenerByDelay', 'Splices the listener into delay order and updates the next scheduled callback time.'],
  ['al', 'a', '(Lmd;)V', 'removeListener', 'Unlinks and releases the listener, then refreshes the next callback countdown from the deque.'],
  ['al', 'c', '(I)V', 'skipSubstreams', 'Advances each retained child stream without producing samples.'],
  ['al', 'c', '([III)V', 'mixSubstreams', 'Invokes active mixing or inactive skipping on every retained child stream.'],
  ['md', 'a', '()V', 'release', 'Abstract callback invoked after this scheduled mixer listener is unlinked.'],
  ['md', 'a', '(Lal;)I', 'onScheduledMix', 'Abstract mixer callback returning the next sample delay or a negative value to remove the listener.'],
  ['e', 'w', '(Z)V', 'disposeNativeResource', 'Native disposal contract invoked directly or from the deferred resource reaper.'],
]) method(owner, original, descriptor, name, evidence);

