Object.assign(classes, {
  aa: ['SpriteMask', 'Abstract sprite/font clipping mask; subclasses retain scanline extents or an OpenGL mask texture.'],
  dm: ['ScanlineSpriteMask', 'SpriteMask with per-row start and width arrays consumed by software masked glyph blits.'],
  lu: ['LegacyOpenGlSpriteMask', 'SpriteMask wrapping the texture used by legacy OpenGL masked glyph drawing.'],
  ae: ['SoundEffect', 'Decodes up to ten synthesized instruments and mixes them to a 22050 Hz PCM sample with loop times.'],
  qg: ['SoundInstrument', 'Synthesizes integer sample data from pitch/volume envelopes, oscillators, gating, delay and an audio filter.'],
  vj: ['SoundEnvelope', 'Piecewise timed envelope with reset, packet decoding and per-sample amplitude interpolation.'],
  re: ['AudioFilter', 'Decodes filter pairs and interpolates attenuation/frequency to compute channel filter coefficients.'],
  dj: ['PlayingSound', 'Intrusive playback record retaining a sample stream, unlink target and original volume for global volume adjustments.'],
  jt: ['CacheReferenceNode', 'Dual-link cache entry with a weight and abstract value and soft-reference queries.'],
  av: ['StrongCacheReference', 'CacheReferenceNode retaining its value directly and reporting that it is not soft.'],
  kl: ['SoftCacheReference', 'CacheReferenceNode retaining a SoftReference, returning its referent and reporting that it is soft.'],
  ag: ['TextLayout', 'Text layout made of line bounds and caret x positions, with hit testing and index-to-position queries.'],
  jd: ['CachedTextLayout', 'TextLayout caching text, font, alignment and dimensions and building single-line or wrapped line metrics.'],
  tk: ['TextLayoutLine', 'Line top/bottom bounds and an array of caret x coordinates, with nearest-caret lookup.'],
  vn: ['LegacyBitmapFont', 'Older bitmap font API retaining glyph widths and line metrics with abstract glyph rendering hooks.'],
  da: ['ToolkitFont', 'Toolkit-backed text renderer with styled text, alignment and abstract plain and masked glyph hooks.'],
  ta: ['FontMetrics', 'Decodes advances and kerning and measures/wraps strings, including inline sprites and formatting tags.'],
  at: ['SoftwareBinaryFont', 'ToolkitFont drawing nonzero glyph-mask bytes as a single color, with optional alpha and scanline masks.'],
  it: ['SoftwareAlphaFont', 'ToolkitFont using unsigned glyph bytes as coverage when blending into the software toolkit raster.'],
  je: ['SoftwarePaletteFont', 'ToolkitFont using glyph bytes as indices into a retained RGB palette.'],
  mv: ['HardwareBitmapFont', 'ToolkitFont uploading glyphs and drawing through a hardware vertex buffer and texture.'],
  qh: ['LegacyOpenGlBitmapFont', 'ToolkitFont using legacy OpenGL texture/display-list drawing and optional mask textures.'],
  n: ['NativePaletteFont', 'Native toolkit font selected for non-monochrome glyphs without an alpha plane.'],
  h: ['NativeMonochromeFont', 'Native toolkit font selected for monochrome glyphs without an alpha plane.'],
  aq: ['DirectSoundDevice', 'Marker interface implemented by the legacy Microsoft DirectSound device wrapper.'],
  uf: ['LegacyDirectSoundDevice', 'Initializes Microsoft DirectSound descriptors and cursor records for two audio buffers.'],
});

