// UI contracts are named at their declarations; binding verification carries
// these names through implementations and inherited call sites.
Object.assign(classes, {
  qm: ['WidgetListener', 'Empty event-listener marker extended by the widget callback interfaces.'],
  ai: ['WidgetActionListener', 'Callback invoked by the interactive widget action dispatcher with its action code and source.'],
  fc: ['WidgetFocusListener', 'Receives a widget and its focused boolean when focus is acquired or cleared.'],
  bd: ['WidgetHoverListener', 'Receives the bounds-hit boolean when a widget changes mouseover state.'],
  nc: ['WidgetScrollListener', 'Receives normalized vertical and horizontal positions from scroll control setters and thumb dragging.'],
  sf: ['WidgetDropListener', 'Receives a draggable widget and its drop target, or null for a release outside a target.'],
  mt: ['WidgetDragListener', 'Receives a draggable widget and parent origins when pointer movement changes its location.'],
  pw: ['TextInputListener', 'Two callbacks invoked separately after text edits and Enter-key submission.'],
  wu: ['WidgetPointerListener', 'Extends the action listener with callbacks dispatched by interactive widget pointer press and release.'],
  ug: ['CompositeWidgetMarker', 'Empty marker implemented by the array-child and single-child widget bases.'],
  mh: ['WidgetRenderer', 'Rendering contract receiving the widget, parent origin and enabled state.'],
  de: ['TextWidgetLayout', 'Text-layout contract exposing dimensions, coordinate hit testing, caret and selection drawing.'],
  gm: ['TextWidgetRenderer', 'Widget renderer and text-layout implementation retaining a bitmap font, padding, alignment and colors.'],
  wp: ['InteractiveWidget', 'Enabled, focusable widget base dispatching actions and optional pointer and focus callbacks.'],
  dh: ['TextInputWidget', 'Interactive widget implementing editable text, caret, selection, clipboard and submission.'],
  ao: ['ArrayWidgetContainer', 'Composite widget traversing a fixed child array for focus, input and rendering.'],
  ie: ['SingleChildWidget', 'Composite widget delegating focus, pointer input, rendering and layout to its retained child.'],
  jh: ['DraggableWidget', 'Single-child widget moved by pointer input, dispatching drag and drop callbacks and animating its return.'],
  st: ['DropTargetWidget', 'Single-child widget accepting the active draggable widget on pointer release.'],
  vo: ['ScrollControl', 'Two-axis normalized scroll control with a draggable thumb, track and optional directional buttons.'],
  mc: ['ScrollPane', 'Array container combining a clipping viewport and horizontal and vertical scroll controls.'],
  we: ['ScrollViewport', 'Single-child widget clipping drawing to its bounds and offsetting the scrolled content.'],
  nd: ['GridWidgetContainer', 'Array container laying out children using row and column counts and weight arrays.'],
  ac: ['FocusProxyWidget', 'Interactive widget overriding focus acquisition to delegate to a retained target widget.'],
  hd: ['DropDownListWidget', 'Dropdown option-list widget retaining an Object array, row metrics and its owning dropdown.'],
  ld: ['DropDownWidget', 'Composite control combining a selected label, toggle button and scrollable option list.'],
  rg: ['ModalDialog', 'Centered widget container owned by a dialog layer, fading its backdrop and children through an offscreen sprite.'],
  hf: ['ResizingDialog', 'Modal dialog subclass interpolating its width and height toward target dimensions.'],
  ur: ['ContentTransitionDialog', 'Resizing dialog wrapping content with padding and retaining replacement content during a transition.'],
  dg: ['DialogLayer', 'Single-child widget with an intrusive stack of modal dialogs rendered over the underlying content.'],
  dd: ['GraphicsOptionsDialog', 'Dialog presenting graphics quality and fullscreen controls and opening display-mode confirmation or errors.'],
  kq: ['FullscreenMembershipDialog', 'Dialog displaying the fullscreen membership message with Members and Close actions.'],
  qk: ['DisplayModeConfirmationDialog', 'Timed display-mode confirmation with Accept and Cancel buttons and a countdown.'],
  u: ['DisplayModeErrorDialog', 'Dialog selecting unsupported configuration, fullscreen failure or cancellation text and offering Close.'],
  m: ['ProgressDialog', 'Modal dialog retaining a message widget and progress indicator.'],
  cv: ['LoginForm', 'Widget container constructing username or email and password inputs and login and guest actions.'],
  pe: ['NameSuggestionsPanel', 'Widget container displaying alternate account names and a More suggestions action.'],
  fo: ['AccountSignupPrompt', 'Container offering Create free account, Go back and play without an account.'],
  lc: ['StatusMessagePanel', 'Message panel with wrapped text and optional action buttons, used as message-dialog content.'],
  gt: ['MessageDialog', 'Content-transition dialog initialized with a status message panel and progress indicator, with configurable follow-up actions.'],
  dc: ['ContentDialog', 'Content-transition dialog subclass wrapping an arbitrary child with a fixed header and transition speeds.'],
  rt: ['LabeledWidget', 'Single-child widget rendering a retained label beside its child; used around the login form text inputs.'],
});

