// resources above. Names follow native allocation, attachment and deletion calls;
// unrelated static helpers remain on their original declaring classes.
Object.assign(classes, {
  ht: ['LegacyOpenGlTexture', 'Base texture owning a GL id, target, internal format, texel count, mipmap/filter state and renderer memory accounting.'],
  us: ['LegacyOpenGlTexture2D', 'Legacy GL texture allocating 2D or rectangle storage with byte, int or float pixels and framebuffer attachments.'],
  f: ['LegacyOpenGlSpriteTexture', '2D texture subclass retaining sprite dimensions and usable UV extents for rectangle, exact-sized or padded storage.'],
  ek: ['LegacyOpenGlTexture3D', 'Allocates target 32879 volume storage, retains width/height/depth and copies framebuffer pixels into a depth slice.'],
  hp: ['LegacyOpenGlCubeTexture', 'Allocates six square faces at GL_TEXTURE_CUBE_MAP_POSITIVE_X plus each face index.'],
  pr: ['LegacyOpenGlTexture1D', 'Allocates target GL_TEXTURE_1D with glTexImage1Dub and sets its S wrap mode.'],
  ft: ['LegacyOpenGlFramebufferAttachment', 'Contract implemented by textures and renderbuffers to detach their retained framebuffer attachment.'],
  mw: ['LegacyOpenGlFramebufferTarget', 'Contract for binding/unbinding read, draw and combined framebuffer targets.'],
  cs: ['LegacyOpenGlFramebuffer', 'Owns a GL framebuffer id, nine texture/renderbuffer attachments and tracked read/draw/combined binding state.'],
  kf: ['LegacyOpenGlRenderbuffer', 'Owns glGenRenderbuffersEXT storage, its dimensions/format, attachment state and deferred deletion.'],
  mk: ['LegacyOpenGlShader', 'Retains the GLSL shader object handle returned by legacy glCreateShaderObjectARB compilation.'],
  sn: ['LegacyOpenGlShaderProgram', 'Retains the GLSL program object handle returned after attaching and linking legacy shader objects.'],
  qj: ['OpenGlShader', 'GLSL shader object created from raw source for the newer OpenGlGraphicsToolkit and deleted through its object queue.'],
  oh: ['OpenGlShaderProgram', 'GLSL linked-program object for the newer OpenGlGraphicsToolkit, with deferred object deletion.'],
  vk: ['LegacyOpenGlAssemblyProgram', 'Legacy GL ARB assembly program id created with glProgramStringARB and queued for glDeleteProgramARB.'],
  wg: ['OpenGlAssemblyProgram', 'Newer toolkit ARB assembly program id created with glProgramRawARB and deferred program deletion.'],
  b: ['LegacyOpenGlNormalMapGenerator', 'Compiles a heightMap fragment shader, renders finite-difference normals per volume slice and copies them into the output texture.'],
  sk: ['WaterTextureResources', 'Hardware water effects consume its animated luminance/alpha volume or slice textures and lazily generated normal-map volume.'],
  mr: ['HardwareTextureCache', 'Builds textures from TextureProvider metadata/pixels and retains them in a 256-entry soft LRU cache.'],
  sd: ['SoftLruCache', 'Weighted cache with a hash table and recency deque, promoting live soft entries and demoting old strong entries.'],
});

