  om: ['DroneWaveDefinition', 'Retains the DroneWave array installed for a decoded custom level and is stored by level id in the level-definition table.'],
  sl: ['LegacyOpenGlClientVertexBuffer', 'Client-memory LegacyOpenGlClientBuffer implementation of LegacyVertexBuffer; its GL buffer id is zero.'],
  rk: ['BufferedImageRasterBuffer', 'RasterBuffer constructing a BufferedImage over its int[] through DataBufferInt, DirectColorModel and WritableRaster.'],
  tw: ['BrowserScriptBridge', 'Only three static entry points, all forwarding to the applet window JSObject eval or call methods.'],
  qn: ['NineSlicePanel', 'Retains a Sprite[] and its sole instance method draws that array using drawNineSlice.'],
  qc: ['DroneIntroductionOverlay', 'Retains the introduced drone type, visibility and a dismissal delay; draws its sprite and droneDescriptions with a delayed click-to-continue prompt.'],
  qt: ['SelectionOverlay', 'Base of the next-level and reset-stats selection overlays, retaining a hovered option and a visibility bit.'],
