  gg: ['ByteArrayCacheNode', 'DualLinkNode retaining a byte array; MusicPatch stores generated seed permutation tables in LruNodeCache using this node.'],
  lm: ['IndexBufferReference', 'Retains a nullable IndexBuffer and closes it through its instance release method.'],
  lr: ['VertexBufferReference', 'Retains a nullable VertexBuffer and closes it through its instance release method.'],
  kk: ['LegacyOpenGlTextureCache', 'Retains a LegacyOpenGlGraphicsToolkit, TextureProvider and SoftLruCache; retrieves or creates LegacyOpenGlTexture2D by texture id.'],
  kg: ['DirectXSwapChainSurface', 'Owns an IDirect3DSwapChain, its backbuffer and a supplied surface, presents the chain and releases all three COM references.'],
  mg: ['ArgbSprite', 'Sprite subclass selected by decoded alpha-plane presence; blit kernels composite the high-byte per-pixel alpha.'],
