Object.assign(classes, {
  ka: ['RenderBufferSet', 'Common parent of HardwareBufferSet and the software/native/legacy-OpenGL buffer-set shells allocated by their render contexts.'],
  af: ['SoftwareRenderBufferSet', 'SoftwareGraphicsToolkit-specific RenderBufferSet shell constructed ten times by SoftwareRenderContext; its capacity constant sizes context scratch indices.'],
  i: ['NativeRenderBufferSet', 'Native RenderBufferSet initialized from the owning toolkit, allocated by NativeRenderContext and finalized through NativeResourceReaper.'],
  lf: ['LegacyOpenGlRenderBufferSet', 'Legacy-OpenGL RenderBufferSet shell constructed with position, texture, normal and color vertex-attribute descriptors.'],
  r: ['DualLinkedRenderResource', 'DualLinkNode base of the native render resource created by the native software toolkit callback; no other instance API remains.'],
  ba: ['NativeDualLinkedRenderResource', 'NativeResource implementation returned by NativeSoftwareGraphicsToolkit native object factory, with deferred native-handle disposal.'],
  hc: ['AccountStatusDialogState', 'Retains the MessageDialog shown and updated by the account/login UI; fonts and gameplay assets are separately moved globals.'],
  im: ['ParticleSpriteResources', 'Retains the shared spark sprite and victory particle deque used by several particle renderers; the toolkit cache and name helper are independent statics.'],
  ke: ['AppletInstanceState', 'Retains the active GameApplet instance checked by applet startup, lifecycle, canvas sizing and browser bridge code.'],
  km: ['FourStatHiscoreRequest', 'Two-byte request matched by id to a leaderboard response containing four statistics per named player and two sorted result sets.'],
  lt: ['FourIntUpdateRequest', 'Queued update with a byte key, signed-smart key and four integer values; the logging response matches both keys before unlinking it.'],
  pd: ['FourIntReadRequest', 'Queued byte/short request whose response consumes four integers and unlinks the oldest pending request.'],
  lq: ['IntroFinalFrameResources', 'Loads the intro final logo and glow resources; keyboard attachment, loading text and transport fields are independent moved statics.'],
  lw: ['CanvasResizeState', 'Retains the minimum canvas height checked during applet resizing and the RESIZING content-transition token.'],
  no: ['LoginFormState', 'Retains the LoginForm created by showLoginForm and installed as the account content; other globals have independent roles.'],
  oi: ['HiscoreRequestQueue', 'Deque is populated and searched by HiscoreRequest and resends the outstanding requests; audio shutdown is an independent static helper.'],
  pc: ['FriendListState', 'Deque contains SocialContact entries inserted and sorted by the friend-update decoder after findFriend lookups.'],
  pi: ['ArenaDefinitionCodec', 'Decodes ArenaDefinition records loaded from levels/; account navigation, noise cache and pointer fields are independent statics.'],
  qf: ['PerlinGradient', 'Computes the hashed two-axis signed gradient dot product used by the three-dimensional Perlin noise generators.'],
  sv: ['RsaEnvelopeScratch', 'Retains the scratch PacketBuffer containing marker 10, four XTEA key words and plaintext length before RSA encryption.'],
  tu: ['CanvasPresentationHook', 'Contains the empty hook called on the active-session path immediately before canvas presentation; no discarded behavior is inferred.'],
  up: ['IntroMeshProjection', 'Transforms intro mesh vertices, projects them through the near plane, transforms optional normals and dispatches face sorting.'],
  vm: ['Base37NameAlphabet', 'Retains underscore, lowercase letters and decimal digits indexed by base-37 player-name decoding.'],
  vp: ['DroneVariantScoring', 'Variant-indexed double multipliers are used by awardDroneDefeatScore before applying the active score multiplier.'],
  wf: ['SnowParticleSpriteData', 'Retains the driftinglight_snow archive sprite data converted into the drifting-light particle toolkit sprite.'],
});

