export const config = {
  game: 'sumoblitz', version: 1, sourceCommit: '32e4691aae4850122db80d30c2db96a06b6b4029', classes, members,
  verifyCore: async () => ({status: 'not-run', note: 'Naming-only pass; no gameplay core fixtures.'}),
  workflowFiles: ['build-sumoblitz-rules.mjs', 'reproduce-sumoblitz.mjs', 'reviewed-game.mjs',
    'pinned-compiler.mjs', 'game-export.mjs', 'compilation-stubs.mjs', 'sumoblitz-string-fields.mjs', 'naming-coverage.mjs'],
  readingGuide(rules, mapping) {
    const coverage = namingCoverage(mapping);
    return ['# Reading Sumo Blitz', '',
      'This directory is the single published Java tree. Reproducible naming rules live in dekobloko-work/readable; the reverse dictionary is ../../decompilation/sumoblitz-naming.json.', '',
      `Resolved declarations: ${coverage.namedClasses}/${coverage.classes} classes and ${coverage.namedMethods}/${coverage.methods} methods have readable names; ${coverage.constructors} constructors follow their class names.`,
      `Remaining: ${coverage.unresolvedClasses.length} opaque class names and ${coverage.unresolvedMethods.length} opaque method names. ${coverage.complete ? 'All resolved class and method declarations have readable names.' : 'The complete naming goal is still in progress.'}`, '',
      'Audit with `node readable/naming-coverage.mjs sumoblitz` in dekobloko-work; it exits unsuccessfully while opaque names remain.', '',
      'Start at `Sumoblitz`; the shared engine (nodes, deques, packet buffer, sockets, widgets, sprites) uses the same role names as other FunOrb games.', '',
      'The obfuscator moved unrelated static helpers between classes. Class names describe retained instance roles; method names describe their own behavior without relocating code.', '',
      'Regeneration compiles the complete raw and renamed sources and verifies resolved bindings, overrides, labels and class-name literals. Full gameplay, native graphics and multiplayer behavior have not been verified by this naming workflow.', '',
      `Decompiler source commit: ${rules.generators.javaTools.commit}.`, ''].join('\n');
  },
};

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const rules = buildReviewedManifest(config), file = path.join(workflowRoot, 'sumoblitz-rules.json');
    const bytes = JSON.stringify(rules, null, 2) + '\n';
    if (process.argv.includes('--check')) {
      if (fs.readFileSync(file, 'utf8') !== bytes) throw new Error('Sumo Blitz rules differ from regeneration');
    } else fs.writeFileSync(file, bytes);
    console.log(JSON.stringify({rules: rules.renames.length, reviewedClasses: Object.keys(classes).length, check: process.argv.includes('--check')}));
  } catch (error) {console.error(error.stderr?.toString() || error.stack); process.exitCode = 1;}
}
